function minValidStrings(words, target) {
  const n = target.length;
  const reach = new Array(n).fill(0);
  for (const word of words) {
    const text = word + '#' + target;
    const z = new Array(text.length).fill(0);
    let left = 0;
    let right = 0;
    for (let i = 1; i < text.length; i++) {
      if (i < right) {
        z[i] = Math.min(right - i, z[i - left]);
      }
      while (i + z[i] < text.length && text.charCodeAt(z[i]) === text.charCodeAt(i + z[i])) {
        z[i]++;
      }
      if (i + z[i] > right) {
        left = i;
        right = i + z[i];
      }
    }
    for (let i = 0; i < n; i++) {
      reach[i] = Math.max(reach[i], z[word.length + 1 + i]);
    }
  }
  let pieces = 0;
  let end = 0;
  let farthest = 0;
  for (let i = 0; i < n; i++) {
    farthest = Math.max(farthest, i + reach[i]);
    if (i === end) {
      if (farthest === end) {
        return -1;
      }
      pieces++;
      end = farthest;
    }
  }
  return pieces;
}

