function minValidStrings(words, target) {
  // best[i] = fewest pieces spelling the first i letters; try every piece that some word starts with.
  const n = target.length;
  const best = new Array(n + 1).fill(Infinity);
  best[0] = 0;
  for (let i = 0; i < n; i++) {
    if (best[i] === Infinity) continue;
    for (let j = i + 1; j <= n; j++) {
      const piece = target.slice(i, j);
      if (!words.some(w => w.startsWith(piece))) break;
      best[j] = Math.min(best[j], best[i] + 1);
    }
  }
  return best[n] === Infinity ? -1 : best[n];
}

