function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const glue = (words, length) => {
    // Random prefixes of the words joined together, so the target can be formed.
    let target = '';
    while (target.length < length) {
      const word = pick(words);
      target += word.slice(0, 1 + Math.floor(rand() * word.length));
    }
    return target.slice(0, length);
  };
  if (size === 'large') {
    const letters = 'abc'.slice(0, 2 + Math.floor(rand() * 2));
    const text = length => Array.from({ length }, () => pick(letters)).join('');
    const short = Array.from({ length: 5 + Math.floor(rand() * 20) }, () => text(1 + Math.floor(rand() * 300)));
    let words, target;
    if (rand() < 0.5) {
      // A periodic target and two long periodic words: every position matches thousands of letters ahead,
      // which defeats walking a trie letter by letter. A few changed letters split the target into pieces.
      const unit = text(1 + Math.floor(rand() * 3));
      const long = unit.repeat(Math.ceil(10001 / unit.length));
      words = [long.slice(0, 5000 + Math.floor(rand() * 5001)), long.slice(1, 2000 + Math.floor(rand() * 5001)), ...letters, ...short];
      const chars = [...long.slice(0, 10000)];
      for (let k = Math.floor(rand() * 4); k > 0; k--) chars[Math.floor(rand() * 10000)] = pick(letters);
      target = chars.join('');
    } else {
      // Random words, three of them long; the total stays far below 10^5 letters.
      words = [...Array.from({ length: 3 }, () => text(2000 + Math.floor(rand() * 8001))), ...short];
      target = glue(words, 10000);
    }
    // Now and then a letter that starts no word makes the target impossible.
    if (rand() < 0.2) {
      const at = Math.floor(rand() * 10000);
      target = target.slice(0, at) + 'z' + target.slice(at + 1);
    }
    return [words, target];
  }
  const letters = 'abc'.slice(0, 1 + Math.floor(rand() * 3));
  const text = length => Array.from({ length }, () => pick(letters)).join('');
  const words = Array.from({ length: 1 + Math.floor(rand() * 4) }, () => text(1 + Math.floor(rand() * 5)));
  const length = 1 + Math.floor(rand() * 10);
  return [words, rand() < 0.7 ? glue(words, length) : text(length)];
}
